  const all=[...state.ontology.terms,...state.ontology.c_nodes],groups=new Map();for(const id of ids){const t=all.find(x=>x.id===id);const k=t.domain==='A'?(t.layer==='A1'?'A1':'A23'):t.domain==='B'?t.layer:'C';if(!groups.has(k))groups.set(k,[]);groups.get(k).push(id)}
