$('#newForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/projects','POST',Object.fromEntries(new FormData(e.target)));$('#newDialog').close();e.target.reset();await openProject(d.id,'artifacts')}catch(err){toast(err.message)}};
window.addEventListener('unhandledrejection',e=>{toast(e.reason?.message||'操作未完成');console.error(e.reason)});
const boot=new URLSearchParams(location.search);(boot.get('sub')?openSub(boot.get('sub')):boot.get('project')?openProject(boot.get('project'),boot.get('tab')||'artifacts'):home()).catch(e=>{toast(e.message);$('#app').innerHTML='<div class="empty">载入失败，请检查服务后刷新。</div>'});


function planningHTML(p){return p&&Object.keys(p).length?`<section class="brief-section"><h3>开发与上市计划</h3><dl>${Object.entries(p).filter(([k,v])=>human(v)).map(([k,v])=>`<div><dt>${esc(({launch_tier:'客户资源分层',development_target:'开发目标',commercialization_target:'商品化目标',launch_timing:'上市节奏',priority_reason:'优先依据',selection_group:'组合总量与约束',selection_role:'本项在组合中的职责'})[k]||'计划')}</dt><dd>${esc(human(v))}</dd></div>`).join('')}</dl></section>`:''}
function coordinationHTML(events){return events?.length?`<section class="brief-section"><h3>项目对接与协调</h3>${events.map(e=>`<div class="item"><strong>${esc(e.action||'协调事项')}</strong><p>${esc([e.owner,e.due_original,e.due_resolved,e.destination,e.quantity,e.purpose].filter(Boolean).join(' · '))}</p>${chip(({planned:'计划中',confirmed:'已确认',done:'已完成'})[e.status]||'待确认')}${refsHTML(e.source_refs)}</div>`).join('')}</section>`:''}
